SELECT ?sensor ?ptype ?ref ?series ?class WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label "Perimeter_top_ZN_2" .
  ?sensor brick:hasLocation ?z .
  ?sensor rdf:type ?ptype .
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?series .
  OPTIONAL { ?sensor brick:hasSubclass* ?class . }
}

SELECT ?sensor ?ptype ?ref ?series WHERE {
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?series .
  FILTER(LCASE(STR(?ptype)) LIKE "%occupan%")
}

SELECT ?sensor ?loc ?locname ?series WHERE {
  ?sensor a brick:Occupancy_Sensor .
  OPTIONAL { ?sensor brick:hasLocation ?loc . ?loc rdfs:label ?locname . }
  OPTIONAL { ?sensor rdfs:label ?slabel . }
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?series .
}

